import heapq

def max_events(events):
    events = sorted(events); h = []; i = 0; n = len(events); day = 0; got = 0
    while i < n or h:
        if not h: day = max(day, events[i][0])
        while i < n and events[i][0] <= day: heapq.heappush(h, events[i][1]); i += 1
        while h and h[0] < day: heapq.heappop(h)
        if h: heapq.heappop(h); got += 1; day += 1
    return got

