int maxEvents(vector<vector<int>>& e) {
    sort(e.begin(), e.end()); priority_queue<int, vector<int>, greater<int>> h; int i = 0, n = e.size(), day = 0, got = 0;
    while (i < n || !h.empty()) { if (h.empty()) day = max(day, e[i][0]); while (i < n && e[i][0] <= day) h.push(e[i++][1]); while (!h.empty() && h.top() < day) h.pop(); if (!h.empty()) { h.pop(); got++; day++; } }
    return got;
}
